"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["41638"],{56182(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>y,frontMatter:()=>p,contentTitle:()=>c,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-fetch-participants-list","title":"Fetch participants list","description":"Payer discovery: lists participants filtered by role, registration date window and optional entity type; the first step of the cashless workflow.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-fetch-participants-list.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-fetch-participants-list","permalink":"/docs/pr-11/docs/nhcx/v1/api/registry/endpoints/registry-fetch-participants-list","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Fetch participants list","sidebar_label":"Fetch participants list","sidebar_class_name":"api-method api-method--post","description":"Payer discovery: lists participants filtered by role, registration date window and optional entity type; the first step of the cashless workflow.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Participant details (v2 search)","permalink":"/docs/pr-11/docs/nhcx/v1/api/registry/endpoints/registry-participant-details"},"next":{"title":"Fetch certificate","permalink":"/docs/pr-11/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs"}}'),n=a(62540),r=a(43023),s=a(44136),o=JSON.parse('{"id":"registry_fetch_participants_list","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/fetch/participants/list","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Fetch participants list","description":"Payer discovery: lists participants filtered by role, registration date window and optional entity type; the first step of the cashless workflow.\\n\\n### Business purpose\\n\\nA patient is not cashless merely by having insurance. The hospital must first discover which payer to deal with, and that payer\'s participantcode becomes the payerId used for NHCX routing and the x-hcx-recipient_code header. This endpoint is the discovery workhorse: it returns every participant of a given role registered within a date window, which is how a hospital builds its payer picker and how a payer sees the providers on the exchange. It is item 1 of the provider sandbox-exit checklist.\\n\\n### When to use\\n\\nCall it at the very start of the handbook\'s fixed operational order: payer search, payer selection, policy discovery, policy cache normalisation, effective payer resolution, InsurancePlan and benefit retrieval, optional eligibility verification, then preauth submission. Refresh the list periodically rather than per patient. Sandbox URL https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/participants/list. Synchronous JSON; no workflow or x-hcx-status codes.\\n\\n### Preconditions\\n\\n- Bearer token in bearer_auth with the Bearer prefix; Accept and Content-Type: application/json.\\n- FetchParticipantRequest: role (PAYER, PROVIDER or TPA), fromdate and todate in dd/MM/yyyy format only, all required; entitytype optional (for example Gov).\\n- A date window wide enough to cover the registration dates of the participants you expect; the handbook example spans 01/04/2021 to 20/03/2026.\\n\\n### Postconditions\\n\\nHTTP 200 with ParticipantListResponse: a participantdetails array of ParticipantDetails with participantcode, participantname, address and state. The handbook notes the response shape is not stable and the documented search logic normalises participantdetails, participants or a raw array. No state changes and no callback. 400, 404 and 500 carry the ErrorResponse envelope. In the sandbox, the dummy payer 1000003538@hcx is the counterparty you will find and use.\\n\\n### Common mistakes\\n\\n- Supplying dates in ISO or any format other than dd/MM/yyyy.\\n- Using a date window that is too narrow, which silently drops payers that registered outside it.\\n- Expecting a name filter; there is none, so text search and GOVT versus PRIVATE classification (from entitytype) must be done client-side.\\n- Being misled by the OpenAPI description, which is copy-pasted from the update API; the request schema defines the real behaviour.\\n- Parsing only participantdetails and breaking when the instance returns participants or a raw array.\\n- Missing Accept header or Bearer prefix.\\n\\n### Best practices\\n\\n- Fetch once with a wide window, cache the list, and filter by name and scheme type locally, as the handbook\'s internal payers endpoint does.\\n- Accept all three response shapes defensively.\\n- Follow selection with /participant/search or /participant/details to confirm status and roles, and /fetch/certs to obtain the certificate before encrypting.\\n- Remove any hard-coded reference to 1000003538@hcx at go-live; production counterparties are resolved from this call.\\n- Refresh the cached list on a schedule so newly registered payers appear.\\n\\n### Related scenario\\n\\nA hospital\'s admission desk opens the cashless screen for a patient holding a government scheme card. The integration has already called /fetch/participants/list with role PAYER, a window from 01/04/2021 to today and entitytype Gov, and cached the result. The desk types the scheme name, the client filters the cached list, and the operator selects the state health agency\'s participantcode. The engine then calls /participant/get/policies to link the patient\'s policy, /fetch/certs for the payer certificate, and submits /v1/insuranceplan/request followed by /v1/preauth/submit.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"role","type":"string","required":false,"description":"","encrypted":false},{"name":"fromdate","type":"string","required":false,"description":"","encrypted":false},{"name":"todate","type":"string","required":false,"description":"","encrypted":false},{"name":"entitytype","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"role":"PAYER","fromdate":"01/04/2021","todate":"20/03/2026","entitytype":"Gov"},"responses":[{"status":"200","description":"HTTP 200 with ParticipantListResponse: a participantdetails array of ParticipantDetails with participantcode, participantname, address and state.","example":{"participantdetails":[{"participantcode":"1000003538@hcx","participantname":"NHCX Dummy Payer","address":"New Delhi","state":"Delhi"},{"participantcode":"1518@hcx","participantname":"Demo Insurance Company","address":"Bengaluru","state":"Karnataka"}]}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/participants/list \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"role\\": \\"PAYER\\",\\n  \\"fromdate\\": \\"01/04/2021\\",\\n  \\"todate\\": \\"20/03/2026\\",\\n  \\"entitytype\\": \\"Gov\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/participants/list \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"role\\": \\"PAYER\\",\\n  \\"fromdate\\": \\"01/04/2021\\",\\n  \\"todate\\": \\"20/03/2026\\",\\n  \\"entitytype\\": \\"Gov\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/participants/list\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"role\\": \\"PAYER\\",\\n        \\"fromdate\\": \\"01/04/2021\\",\\n        \\"todate\\": \\"20/03/2026\\",\\n        \\"entitytype\\": \\"Gov\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/participants/list\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"role\\": \\"PAYER\\",\\n    \\"fromdate\\": \\"01/04/2021\\",\\n    \\"todate\\": \\"20/03/2026\\",\\n    \\"entitytype\\": \\"Gov\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let p={title:"Fetch participants list",sidebar_label:"Fetch participants list",sidebar_class_name:"api-method api-method--post",description:"Payer discovery: lists participants filtered by role, registration date window and optional entity type; the first step of the cashless workflow.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},c,d={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:o})}function y(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);